code.init:
// GRAVITY BOX
szx=3; szy=3; n=50; objs=4;
index=-1; t=gettime(0);

code.perFrame:
slow=reg00;
vol=reg80;
asp=w/h; index=0;
foo1=foo1+slow*ran1*vol;
reg50=foo1;
p=0;

code.perPoint:
// Draw Objects
yb=cos(i*$pi*2+foo1);
xb=sin(i*$pi*2+foo1);
zb=gmegabuf(p*20)*0.5;
p=p+1;
/* Position Set */
x1=xb+reg08; y1=yb+reg07; z1=zb+reg08;
x1=xb;y1=yb;z1=zb;

/* 3D Movements */
x2=x1*reg03-y1*reg06; y2=x1*reg06+y1*reg03;
z2=x2*reg05+z1*reg02; x3=x2*reg02-z1*reg05;
y3=y2*reg01-z2*reg04; z3=y2*reg04+z2 *reg01;

/* 2D Conversion */
iz=1/(z3+objs+if(reg09,-.4+reg09,0));
x=x3*iz*1.3; y=y3*iz*asp;
sizex=iz*szx; sizey=iz*szy;

// Skip Behind Camera
skip=below(iz,0);

